 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            # A rectangular outline encloses a region. The 3x3 outline denotes a single special center.
            if r1-r0 >= 2 and c1-c0 >= 2:
                perimeter = {(y, x) for y in range(r0, r1+1) for x in range(c0, c1+1)
                             if y in (r0, r1) or x in (c0, c1)}
                if all(grid[y][x] == color for y, x in perimeter):
                    fill = 7 if (r1-r0 == 2 and c1-c0 == 2) else 2
                    for y in range(r0+1, r1):
                        for x in range(c0+1, c1):
                            if grid[y][x] == background:
                                out[y][x] = fill
    return out

if __name__ == '__main__':
    pass
